const $=s=>document.querySelector(s);
const gcd=(a,b)=>{a=Math.abs(a);b=Math.abs(b);while(b)[a,b]=[b,a%b];return a;};
const rnd=x=>Math.round(x*1000)/1000;
const ans=x=>String(rnd(x)).replace('.',',');
const pick=arr=>arr[Math.floor(Math.random()*arr.length)];
const shuffle=arr=>{const c=arr.slice();for(let i=c.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[c[i],c[j]]=[c[j],c[i]];}return c;};
function mulberry32(seed){let a=seed>>>0;return function(){a=(a+0x6D2B79F5)|0;let t=a;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};}
function makeRng(seed){const f=mulberry32(seed);return{next:()=>f(),int:(a,b)=>a+Math.floor(f()*(b-a+1)),pick:arr=>arr[Math.floor(f()*arr.length)],shuffle:arr=>{const c=arr.slice();for(let i=c.length-1;i>0;i--){const j=Math.floor(f()*(i+1));[c[i],c[j]]=[c[j],c[i]];}return c;}};}
function frac(n,d){return`<span class="frac"><span class="frac-n">${n}</span><span class="frac-d">${d}</span></span>`;}
function fmtAnswer(a){if(/^-?\d+\/\d+$/.test(a)){const[n,d]=a.split('/');return frac(n,d);}return a;}
function normalize(s){if(s===undefined||s===null)return'';return String(s).replace(/\s+/g,'').replace(/−/g,'-').replace(/,/g,'.').replace(/х/g,'x').replace(/·/g,'*').replace(/[²]/g,'^2').replace(/[³]/g,'^3').toLowerCase();}
function parseNumeric(s){if(!s)return null;const fm=s.match(/^(-?\d+(?:\.\d+)?)\/(-?\d+(?:\.\d+)?)$/);if(fm){const v=parseFloat(fm[1])/parseFloat(fm[2]);return isFinite(v)?v:null;}if(/^-?\d+(?:\.\d+)?$/.test(s))return parseFloat(s);return null;}
function check(user,task){const u=normalize(user),c=normalize(task.answer);if(!u)return false;if(u===c)return true;const nu=parseNumeric(u),nc=parseNumeric(c);if(nu!==null&&nc!==null&&Math.abs(nu-nc)<1e-6)return true;return false;}
function factorial(n){let f=1;for(let i=2;i<=n;i++)f*=i;return f;}
const options=list=>'<ol class="opts">'+list.map(x=>`<li>${x}</li>`).join('')+'</ol>';

