function squaresTable(){const head='<tr><th></th>'+[...Array(10)].map((_,u)=>`<th>${u}</th>`).join('')+'</tr>';const rows=[...Array(9)].map((_,t)=>`<tr><th>${t+1}</th>`+[...Array(10)].map((_,u)=>`<td>${((t+1)*10+u)**2}</td>`).join('')+'</tr>').join('');return`<h4>Таблица квадратов (10–99)</h4><div class="tbl"><table>${head}${rows}</table></div>`;}
function squaresInline(){const head='<tr><th>n</th><th>n²</th><th>n</th><th>n²</th></tr>';const rows=[];for(let i=1;i<=20;i++)rows.push(`<tr><td>${i}</td><td>${i*i}</td><td>${i+20}</td><td>${(i+20)*(i+20)}</td></tr>`);return`<h4>Таблица квадратов (1–40)</h4><div class="tbl"><table>${head}${rows.join('')}</table></div>`;}
const TRIG_ANGLES=[['0°','0','1','0'],['30°',frac(1,2),frac('√3',2),frac('√3',3)],['45°',frac('√2',2),frac('√2',2),'1'],['60°',frac('√3',2),frac(1,2),'√3'],['90°','1','0','–'],['120°',frac('√3',2),'−'+frac(1,2),'−√3'],['135°',frac('√2',2),'−'+frac('√2',2),'−1'],['150°',frac(1,2),'−'+frac('√3',2),'−'+frac('√3',3)],['180°','0','−1','0']];
function trigTables(){const s=TRIG_ANGLES.map(([a,s,c,t])=>`<tr><th>${a}</th><td>${s}</td><td>${c}</td><td>${t}</td></tr>`).join('');return'<h4>Синусы и косинусы основных углов</h4><div class="tbl"><table><tr><th>α</th><th>sin α</th><th>cos α</th><th>tg α</th></tr>'+s+'</table></div>';}
