const EX=(title,body)=>`<div class="example"><b>Пример: ${title}</b><br>${body}</div>`;

const THEORY={
'g8-reduce':`<h4>Основное свойство дроби</h4><p>Если числитель и знаменатель умножить или разделить на одно и то же ненулевое выражение, значение дроби не изменится.</p><p><b>Формулы:</b> ${frac('a','b')} = ${frac('a·c','b·c')}, c ≠ 0.</p><h4>Алгоритм сокращения</h4><ul><li>Разложить числитель на множители.</li><li>Разложить знаменатель на множители.</li><li>Сократить общие множители.</li></ul><p><b>Важно:</b> сокращать можно только <b>множители</b>, а не слагаемые.</p><h4>Формулы для разложения</h4><p>a² − b² = (a−b)(a+b); a² ± 2ab + b² = (a±b)²; a³ ± b³ = (a±b)(a²∓ab+b²).</p>${EX('(x² − 9)/(x + 3)','<b>Шаг 1.</b> Числитель — разность квадратов: x² − 9 = (x−3)(x+3).<br><b>Шаг 2.</b> Знаменатель: (x+3).<br><b>Шаг 3.</b> Сокращаем на (x+3): получаем x − 3 (при x ≠ −3).')}`,
'g8-sameDen':`<h4>Правило</h4><p>${frac('a','c')} + ${frac('b','c')} = ${frac('a+b','c')}; ${frac('a','c')} − ${frac('b','c')} = ${frac('a−b','c')}.</p><p>Знаменатель не меняется, работаем только с числителями.</p>${EX('(x+1)/(x+2) + 3/(x+2)','<b>Шаг 1.</b> Складываем числители: (x+1) + 3 = x+4.<br><b>Шаг 2.</b> Записываем дробь: (x+4)/(x+2), x ≠ −2.<br><b>Внимание:</b> (x+4)/(x+2) ≠ 4/2 — сокращать слагаемые нельзя.')}`,
'g8-diffDen':`<h4>Алгоритм приведения</h4><ul><li>Разложить каждый знаменатель.</li><li>Найти НОЗ — наименьший общий знаменатель.</li><li>Найти дополнительные множители.</li><li>Умножить каждую дробь на свой доп. множитель.</li><li>Сложить (вычесть) числители, знаменатель оставить общим.</li><li>Сократить, если можно.</li></ul><p><b>Полезно:</b> b − a = −(a − b).</p>${EX('1/x + 1/y','<b>Шаг 1.</b> НОЗ = xy.<br><b>Шаг 2.</b> Доп. множители: y и x.<br><b>Шаг 3.</b> y/(xy) + x/(xy) = (x+y)/(xy).')}`,
'g8-mul':`<h4>Правило</h4><p>${frac('a','b')} · ${frac('c','d')} = ${frac('a·c','b·d')}.</p><h4>Алгоритм</h4><ul><li>Разложить всё на множители.</li><li>Сократить общие множители (крест-накрест тоже можно).</li><li>Перемножить оставшиеся числители и знаменатели.</li></ul>${EX('(x² − 4)/(x+3) · (x+3)/(x−2)','<b>Шаг 1.</b> x² − 4 = (x−2)(x+2).<br><b>Шаг 2.</b> Сокращаем (x+3) и (x−2):<br>(x−2)(x+2)/(x+3) · (x+3)/(x−2) = x + 2 (при x ≠ −3, x ≠ 2).')}`,
'g8-div':`<h4>Правило</h4><p>${frac('a','b')} : ${frac('c','d')} = ${frac('a','b')} · ${frac('d','c')}.</p><p>Деление заменяется умножением на обратную дробь.</p>${EX('(x² − 9)/(x−1) : (x−3)/(x−1)','<b>Шаг 1.</b> Переворачиваем вторую дробь: (x²−9)/(x−1) · (x−1)/(x−3).<br><b>Шаг 2.</b> x²−9 = (x−3)(x+3).<br><b>Шаг 3.</b> Сокращаем: остаётся x + 3 (при x ≠ 1, x ≠ 3).')}`,
'g8-root-basic':`<h4>Определение</h4><p>√a = b означает: b ≥ 0 и b² = a.</p><p>Подкоренное выражение должно быть неотрицательным: a ≥ 0.</p><h4>Свойства</h4><p>(√a)² = a при a ≥ 0; √(a²) = |a| для любого a.</p>${EX('√144','<b>Шаг 1.</b> Ищем число, квадрат которого 144.<br><b>Шаг 2.</b> 12² = 144, значит √144 = 12.<br>Другие примеры: (√7)² = 7, √((−3)²) = |−3| = 3.')}${squaresInline()}`,
'g8-root-props':`<h4>Корень из произведения</h4><p>√(a·b) = √a · √b при a ≥ 0, b ≥ 0.</p><h4>Корень из дроби</h4><p>√(a/b) = √a/√b при a ≥ 0, b > 0.</p>${EX('√12 · √3','<b>Шаг 1.</b> По свойству: √12 · √3 = √(12·3) = √36.<br><b>Шаг 2.</b> √36 = 6.')}${EX('√27 / √3','√27/√3 = √(27/3) = √9 = 3.')}`,
'g8-root-transform':`<h4>Ключевые тождества</h4><ul><li>(√a)² = a при a ≥ 0</li><li>√(a²) = |a|</li><li>√(ab) = √a·√b</li><li>√(a/b) = √a/√b</li></ul>${EX('(√3 + √12)²','<b>Шаг 1.</b> Раскрываем как квадрат суммы: (√3)² + 2·√3·√12 + (√12)².<br><b>Шаг 2.</b> (√3)² = 3, (√12)² = 12, √3·√12 = √36 = 6.<br><b>Шаг 3.</b> 3 + 2·6 + 12 = 27.')}`,
'g8-quad-eq':`<h4>Определение</h4><p>ax² + bx + c = 0, a ≠ 0.</p><h4>Дискриминант</h4><p>D = b² − 4ac.</p><ul><li>D > 0 — два корня</li><li>D = 0 — один корень</li><li>D < 0 — корней нет</li></ul><p><b>Формула корней:</b> x = ${frac('−b ± √D','2a')}.</p><h4>Неполные уравнения</h4><p>ax² + bx = 0 → x(ax+b) = 0 → x₁ = 0, x₂ = −${frac('b','a')}.</p><p>ax² + c = 0 → x² = −${frac('c','a')}.</p>${EX('2x² − 7x + 3 = 0','<b>Шаг 1.</b> D = (−7)² − 4·2·3 = 49 − 24 = 25.<br><b>Шаг 2.</b> √D = 5.<br><b>Шаг 3.</b> x = (7 ± 5)/4 → x₁ = 3, x₂ = ½.')}`,
'g8-vieta':`<h4>Теорема Виета</h4><p>Для приведённого x² + px + q = 0 с корнями x₁, x₂:</p><p>x₁ + x₂ = −p, x₁ · x₂ = q.</p><h4>Обратная теорема</h4><p>Если m + n = −p и m·n = q, то m и n — корни x² + px + q = 0.</p><h4>Тождества</h4><p>x₁² + x₂² = (x₁+x₂)² − 2x₁x₂;</p><p>(x₁−x₂)² = (x₁+x₂)² − 4x₁x₂.</p>${EX('x² − 5x + 6 = 0','<b>Шаг 1.</b> p = −5, q = 6.<br><b>Шаг 2.</b> Сумма корней = 5, произведение = 6.<br>Подбором: 2 и 3.')}`,
'g8-frac-eq':`<h4>Что это</h4><p>Уравнение, где хотя бы одна часть — дробь с переменной в знаменателе.</p><h4>Алгоритм</h4><ol><li>Найти ОДЗ — знаменатели ≠ 0.</li><li>Найти общий знаменатель.</li><li>Умножить обе части на общий знаменатель.</li><li>Решить целое уравнение.</li><li>Проверить по ОДЗ, посторонние отбросить.</li></ol>${EX('2/(x−1) + 1/(x−2) = 2','<b>Шаг 1.</b> ОДЗ: x ≠ 1, x ≠ 2.<br><b>Шаг 2.</b> Общий знаменатель (x−1)(x−2).<br><b>Шаг 3.</b> 2(x−2) + 1(x−1) = 2(x−1)(x−2).<br><b>Шаг 4.</b> 2x−4+x−1 = 2x²−6x+4 → 2x²−9x+9 = 0 → x = 3 или 1,5.<br><b>Шаг 5.</b> Оба не равны 1 и 2 — оба подходят.')}`,
'g8-root-eq':`<h4>Уравнения вида √f(x) = g(x)</h4><p>Самый частый случай: корень с одной стороны, выражение без корня — с другой.</p><h4>Алгоритм</h4><ol><li>Уединить корень (оставить его одного в части уравнения).</li><li>Возвести обе части в квадрат.</li><li>Решить получившееся уравнение.</li><li>Проверить корни в исходном уравнении — при возведении в квадрат могут появиться посторонние корни.</li></ol><p><b>Дополнительно:</b> правая часть g(x) должна быть неотрицательной, иначе корней нет.</p>${EX('√(x+5) = x−1','<b>Шаг 1.</b> Корень уже уединён.<br><b>Шаг 2.</b> x + 5 = (x−1)² = x² − 2x + 1.<br><b>Шаг 3.</b> x² − 3x − 4 = 0 → (x−4)(x+1) = 0 → x = 4 или x = −1.<br><b>Шаг 4.</b> Проверка:<br>• x = 4: √9 = 3, 4 − 1 = 3 ✓;<br>• x = −1: √4 = 2, −1 − 1 = −2 ✗ — посторонний.<br><b>Ответ:</b> x = 4.')}`,
'g8-quad-trin':`<h4>Определение</h4><p>Квадратный трёхчлен — многочлен вида ax² + bx + c, где a ≠ 0.</p><h4>Корни трёхчлена</h4><p>Это корни уравнения ax² + bx + c = 0.</p><p>Дискриминант D = b² − 4ac определяет количество корней:</p><ul><li>D > 0 — два корня</li><li>D = 0 — один корень (двойной)</li><li>D < 0 — корней нет</li></ul>${EX('Найти корни трёхчлена x² − 5x + 6','<b>Шаг 1.</b> Приравниваем к нулю: x² − 5x + 6 = 0.<br><b>Шаг 2.</b> По теореме Виета: x₁ + x₂ = 5, x₁·x₂ = 6.<br><b>Шаг 3.</b> Подбором: 2 и 3.<br><b>Проверка:</b> 2² − 5·2 + 6 = 4 − 10 + 6 = 0 ✓.')}${EX('Сколько корней у 2x² − 4x + 5?','<b>Шаг 1.</b> D = (−4)² − 4·2·5 = 16 − 40 = −24.<br><b>Шаг 2.</b> D < 0 → корней нет.')}${EX('При каком c у x² + 6x + c один корень?','<b>Шаг 1.</b> D = 6² − 4c = 36 − 4c.<br><b>Шаг 2.</b> Один корень ⇔ D = 0 ⇔ c = 9.<br><b>Проверка:</b> x² + 6x + 9 = (x+3)² — действительно полный квадрат.')}`,
'g8-factor-trin':`<h4>Теорема</h4><p>Если x₁, x₂ — корни квадратного трёхчлена ax² + bx + c, то</p><p><b>ax² + bx + c = a(x − x₁)(x − x₂).</b></p><h4>Алгоритм</h4><ol><li>Найти корни уравнения ax² + bx + c = 0.</li><li>Подставить в формулу a(x − x₁)(x − x₂).</li><li>При необходимости перегруппировать.</li></ol><h4>Формулы</h4><p>a² − b² = (a − b)(a + b)</p><p>a³ ± b³ = (a ± b)(a² ∓ ab + b²)</p>${EX('x² − 5x + 6','<b>Шаг 1.</b> Корни 2 и 3.<br><b>Шаг 2.</b> Разложение: (x − 2)(x − 3).')}${EX('2x² − 7x + 3','<b>Шаг 1.</b> D = 49 − 24 = 25, корни: 3 и ½.<br><b>Шаг 2.</b> 2(x − 3)(x − ½).<br><b>Шаг 3.</b> Переписываем красивее: (x − 3)(2x − 1).')}${EX('x² − 25','<b>Шаг 1.</b> Это разность квадратов: x² − 5².<br><b>Шаг 2.</b> Раскладываем: (x − 5)(x + 5).')}`,
'g8-lin-ineq':`<h4>Определение</h4><p>ax > b, ax < b, ax ≥ b, ax ≤ b.</p><h4>Правила</h4><ul><li>Слагаемое переносится с противоположным знаком.</li><li>При умножении/делении на положительное число знак сохраняется.</li><li>При умножении/делении на отрицательное число знак <b>меняется на противоположный</b>.</li></ul>${EX('−2x + 5 < 1','<b>Шаг 1.</b> Переносим 5: −2x < 1 − 5 = −4.<br><b>Шаг 2.</b> Делим на −2, знак меняем: x > 2.<br>Наименьшее целое решение: 3.')}`,
'g8-sys-ineq':`<h4>Определение</h4><p>Решение системы — пересечение решений каждого неравенства.</p><h4>Алгоритм</h4><ol><li>Решить каждое неравенство отдельно.</li><li>Отметить решения на одной числовой прямой.</li><li>Найти пересечение (общую часть).</li></ol>${EX('{ 2x−1 > 3, x+4 < 10 }','<b>Шаг 1.</b> 2x > 4 → x > 2.<br><b>Шаг 2.</b> x < 6.<br><b>Шаг 3.</b> Пересечение (2; 6). Целые: 3, 4, 5 — всего 3.')}`,
'g8-fn-domain':`<h4>Функция</h4><p>Зависимость, при которой каждому x соответствует единственное y.</p><h4>Область определения</h4><ul><li>Знаменатель ≠ 0.</li><li>Под корнем чётной степени выражение ≥ 0.</li></ul><h4>Нуль функции</h4><p>Значение x, при котором f(x) = 0.</p>${EX('f(x) = 3x − 12','<b>Шаг 1.</b> Приравниваем к нулю: 3x − 12 = 0.<br><b>Шаг 2.</b> 3x = 12 → x = 4.<br>Нуль функции: x = 4.')}`,
'g8-linear-fn':`<h4>Свойства y = kx + b</h4><ul><li>k > 0 — возрастает, k < 0 — убывает, k = 0 — постоянна.</li><li>График — прямая; проходит через (0; b).</li><li>Пересекает Ox при x = −b/k.</li></ul><h4>Параллельность</h4><p>y = k₁x + b₁ ∥ y = k₂x + b₂ ⇔ k₁ = k₂.</p>${EX('y = kx − 3 ∥ y = 4x + 1','<b>Шаг 1.</b> По условию параллельности k₁ = k₂.<br><b>Шаг 2.</b> k = 4.')}`,
'g8-frac-sqrt-fn':`<h4>y = k/x</h4><p>Обратная пропорциональность, x ≠ 0. График — гипербола. При k > 0 в I и III четвертях, при k < 0 во II и IV.</p><h4>y = √x</h4><p>Область определения x ≥ 0. График — правая ветвь параболы.</p>${EX('y = 6/x при x = 3','y = 6/3 = 2.')}${EX('√x = 3','x = 3² = 9.')}`,
'g8-neg-pow':`<h4>Определение</h4><p>a⁻ⁿ = ${frac(1,'aⁿ')}, a ≠ 0.</p><h4>Почему так</h4><p>Хотим aᵐ · a⁻ᵐ = a⁰ = 1, значит a⁻ᵐ = 1/aᵐ.</p>${EX('2⁻³','2⁻³ = 1/2³ = 1/8.')}${EX('(1/2)⁻³','(1/2)⁻³ = 2³ = 8.')}${EX('(2/3)⁻²','(2/3)⁻² = (3/2)² = 9/4.')}`,
'g8-pow-props':`<h4>Свойства</h4><ul><li>aᵐ · aⁿ = aᵐ⁺ⁿ</li><li>aᵐ : aⁿ = aᵐ⁻ⁿ</li><li>(aᵐ)ⁿ = aᵐⁿ</li><li>(ab)ⁿ = aⁿbⁿ, (a/b)ⁿ = aⁿ/bⁿ</li></ul>${EX('2⁻³ · 2⁵','<b>Шаг 1.</b> 2⁻³ · 2⁵ = 2⁻³⁺⁵ = 2².<br><b>Шаг 2.</b> 2² = 4.')}`,
'g8-std-form':`<h4>Определение</h4><p>a · 10ⁿ, где 1 ≤ a < 10, n — целое (порядок).</p><h4>Перевод</h4><ul><li>Большое число → n > 0, запятая сдвигается влево.</li><li>Малое число → n < 0, запятая сдвигается вправо.</li></ul><p><b>Умножение:</b> (a·10ᵐ)(b·10ⁿ) = (ab)·10ᵐ⁺ⁿ.</p>${EX('520 000','520 000 = 5,2 · 10⁵.')}${EX('0,00052','0,00052 = 5,2 · 10⁻⁴.')}`,
'g9-quad-vertex':`<h4>Вершина параболы y = ax² + bx + c</h4><p>x₀ = −${frac('b','2a')}, y₀ = f(x₀).</p><p>При a > 0 в вершине минимум, при a < 0 — максимум.</p><h4>Вершинная форма</h4><p>y = a(x−m)² + n, вершина (m; n).</p><p>Если известна вершина (m; n) и точка (p; q): a = ${frac('q − n','(p − m)²')}.</p>${EX('y = x² − 6x + 5','<b>Шаг 1.</b> x₀ = −(−6)/(2·1) = 3.<br><b>Шаг 2.</b> y₀ = 3² − 6·3 + 5 = −4.<br>Вершина (3; −4).')}`,
'g9-quad-graph':`<h4>График</h4><p>Парабола. a > 0 — ветви вверх, a < 0 — вниз.</p><h4>Нули функции</h4><p>Корни ax² + bx + c = 0.</p><h4>Знак</h4><p>y > 0 — выше Ox, y < 0 — ниже.</p>${EX('x² − 5x + 6 < 0','<b>Шаг 1.</b> Корни: x = 2 и x = 3.<br><b>Шаг 2.</b> Ветви вверх → функция < 0 между корнями: (2; 3).<br><b>Шаг 3.</b> Целых чисел нет. Ответ: 0.')}`,
'g9-root-n':`<h4>Определение</h4><p>ⁿ√a = b ⇔ bⁿ = a.</p><p>При чётном n: a ≥ 0, b ≥ 0. При нечётном: a любое, b имеет знак a.</p>${EX('∛27','∛27 = 3, т.к. 3³ = 27.')}${EX('⁵√(−32)','⁵√(−32) = −2, т.к. (−2)⁵ = −32.')}`,
'g9-quad-ineq':`<h4>Неравенства ax² + bx + c > 0 (или < 0)</h4><h4>Алгоритм</h4><ol><li>Найти корни r₁ < r₂ уравнения = 0.</li><li>Схема знаков параболы.</li><li>При a > 0: «+» вне корней, «−» между.</li></ol>${EX('x² − 5x + 6 < 0','<b>Шаг 1.</b> Корни 2 и 3.<br><b>Шаг 2.</b> Ветви вверх → «−» между корнями.<br>Ответ: (2; 3).')}`,
'g9-interval':`<h4>Метод интервалов</h4><ol><li>Найти нули числителя и знаменателя.</li><li>Отметить их на числовой прямой.</li><li>Определить знак в крайнем правом интервале.</li><li>Чередовать знаки при переходе через простой корень.</li></ol>${EX('(x−2)(x+1) > 0','<b>Шаг 1.</b> Нули: x = 2 и x = −1.<br><b>Шаг 2.</b> Промежутки: (−∞; −1), (−1; 2), (2; +∞).<br><b>Шаг 3.</b> При x > 2 оба множителя «+».<br><b>Шаг 4.</b> Чередуем: «+ − +».<br>Ответ: (−∞; −1) ∪ (2; +∞).')}`,
'g9-whole-eq':`<h4>Целые уравнения</h4><h4>Биквадратное: ax⁴ + bx² + c = 0</h4><p>Замена t = x², t ≥ 0.</p>${EX('x⁴ − 13x² + 36 = 0','<b>Шаг 1.</b> t = x², t² − 13t + 36 = 0.<br><b>Шаг 2.</b> t₁ = 4, t₂ = 9.<br><b>Шаг 3.</b> x² = 4 → x = ±2; x² = 9 → x = ±3.<br>Ответ: ±2, ±3.')}<h4>Кубическое</h4><p>Сумма корней x³ + px² + qx + r = 0 равна −p.</p>`,
'g9-graph-sys':`<h4>Графический способ</h4><ol><li>Построить графики обоих уравнений.</li><li>Найти точки пересечения.</li></ol><h4>Количество решений</h4><p>y = x² и y = kx + b: решаем x² − kx − b = 0.</p><p>D = k² + 4b. D > 0 — 2 точки, D = 0 — 1, D < 0 — 0.</p>${EX('y = x² и y = 2x + 3','<b>Шаг 1.</b> x² = 2x + 3 → x² − 2x − 3 = 0.<br><b>Шаг 2.</b> D = 4 + 12 = 16, x = (2 ± 4)/2 = 3 или −1.<br>Две общие точки.')}`,
'g9-sys-quad':`<h4>Системы второй степени</h4><p>Если одно уравнение линейное — подстановка.</p><p>Если симметричная — замена u = x + y, v = xy.</p>${EX('{ x+y = 5, xy = 6 }','<b>Шаг 1.</b> x и y — корни t² − 5t + 6 = 0.<br><b>Шаг 2.</b> t = 2 или t = 3.<br><b>Шаг 3.</b> Решения (2; 3) и (3; 2).')}`,
'g9-ineq-vars':`<h4>Неравенства с двумя переменными</h4><p>Решение — множество точек плоскости.</p><p>y > f(x) — выше графика; y < f(x) — ниже.</p>${EX('x,y ≥ 0, x+y ≤ 3','Целые точки: (0,0), (0,1), (0,2), (0,3), (1,0), (1,1), (1,2), (2,0), (2,1), (3,0). Всего 10.')}`,
'g9-arith':`<h4>Арифметическая прогрессия</h4><p>Каждый член, начиная со второго, равен предыдущему плюс d.</p><p>aₙ = a₁ + d(n−1); Sₙ = ${frac('(a₁ + aₙ)·n',2)}.</p>${EX('a₁ = 2, d = 3','<b>Шаг 1.</b> a₁₀ = 2 + 3·9 = 29.<br><b>Шаг 2.</b> S₁₀ = (2+29)·10/2 = 155.')}`,
'g9-geom':`<h4>Геометрическая прогрессия</h4><p>Каждый член равен предыдущему, умноженному на q.</p><p>bₙ = b₁·qⁿ⁻¹; Sₙ = ${frac('b₁(qⁿ − 1)','q − 1')} при q ≠ 1.</p>${EX('b₁ = 2, q = 3','<b>Шаг 1.</b> b₅ = 2·3⁴ = 162.<br><b>Шаг 2.</b> S₄ = 2(3⁴ − 1)/(3 − 1) = 2·80/2 = 80.')}`,
'g9-prog-mix':`<h4>Смешанные задачи</h4><p>Используйте формулы обеих прогрессий.</p><p><b>Свойство арифметической:</b> aₙ = ${frac('aₙ₋₁ + aₙ₊₁',2)}.</p>${EX('3, x, 11 — арифметическая прогрессия','x = (3 + 11)/2 = 7.')}`,
'g9-comb':`<h4>Комбинаторика</h4><p>n! = 1·2·...·n, 0! = 1.</p><p>Pₙ = n!.</p><p>A(n;k) = ${frac('n!','(n−k)!')}.</p><p>C(n;k) = ${frac('n!','k!(n−k)!')}.</p>${EX('C(7;3)','<b>Шаг 1.</b> Порядок не важен → сочетания.<br><b>Шаг 2.</b> C(7;3) = 7!/(3!·4!) = 5040/(6·24) = 35.')}`,
'g9-prob':`<h4>Классическая вероятность</h4><p>P(A) = ${frac('m','n')}, где m — благоприятные, n — все равновозможные исходы.</p><p>P(не A) = 1 − P(A).</p>${EX('12 карандашей, 3 красных','<b>Шаг 1.</b> n = 12, m = 3.<br><b>Шаг 2.</b> P = 3/12 = 1/4 = 0,25.')}`,
'g9-freq':`<h4>Относительная частота</h4><p>Частота = ${frac('m','n')}, где m — наступлений, n — всего испытаний.</p><p>При большом n частота приближается к вероятности.</p>${EX('200 деталей, 12 бракованных','Частота брака = 12/200 = 0,06.')}`
};

function polyStr(a,b,c){let s;if(a===1)s='x²';else if(a===-1)s='−x²';else s=`${a}x²`;if(b!==0)s+=b>0?` + ${b}x`:` − ${Math.abs(b)}x`;if(c!==0)s+=c>0?` + ${c}`:` − ${Math.abs(c)}`;return s;}
const fFr=r=>r<0?`(x + ${Math.abs(r)})`:`(x − ${Math.abs(r)})`;

const GENERATORS={
reduceFraction:{easy(rng){const a=rng.int(2,9),b=rng.int(2,9),g=gcd(a,b)||1,k=rng.int(2,5),v=rng.pick(['x','a','b','y']),na=a/g,da=b/g;return{prompt:`Сократите дробь ${frac(`${k*a}${v}`,`${k*b}${v}`)}.`,answer:na===da?'1':(da===1?String(na):`${na}/${da}`),solution:`${frac(`${k*a}${v}`,`${k*b}${v}`)} = ${frac(`${na}${v}`,`${da}${v}`)} = ${da===1?na:frac(na,da)}.`};},medium(rng){const a=rng.int(2,9),v=rng.pick(['x','a','b','m']);return{prompt:`Сократите дробь ${frac(`${v}² − ${a*a}`,`${v} − ${a}`)}.`,answer:`${v}+${a}`,solution:`Разность квадратов: ${v}²−${a*a} = (${v}−${a})(${v}+${a}). Ответ: ${v} + ${a}.`};},hard(rng){const a=rng.int(2,5),k=a+rng.int(3,6),val=k-a;return{prompt:`Упростите ${frac(`x²−${2*a}x+${a*a}`,`x−${a}`)} и найдите значение при x = ${k}.`,answer:String(val),solution:`(x−${a})² сокращаем: x − ${a}.<br>При x=${k}: ${val}.`};}},
sameDen:{easy(rng){const a=rng.int(1,9),b=rng.int(1,9),c=rng.int(2,9),g=gcd(a+b,c)||1;return{prompt:`Вычислите: ${frac(a,c)} + ${frac(b,c)}.`,answer:(c/g===1)?String((a+b)/g):`${(a+b)/g}/${c/g}`,solution:`${frac(a+b,c)}${g>1?' = '+frac((a+b)/g,c/g):''}.`};},medium(rng){const b=rng.int(3,6),a=rng.int(1,b-1);return{prompt:`Упростите: ${frac(`x+${a}`,`x+${b}`)} + ${frac(b-a,`x+${b}`)}.`,answer:'1',solution:`${frac(`x+${b}`,`x+${b}`)} = 1.`};},hard(rng){const a=rng.int(1,4),b=rng.int(2,6),k=a+b+rng.int(1,3);return{prompt:`Упростите ${frac(`x²+${a}x`,`x−${b}`)} − ${frac(`${b}x+${a*b}`,`x−${b}`)} и найдите при x = ${k}.`,answer:String(k+a),solution:`(x−${b})(x+${a}) / (x−${b}) = x+${a}. При x=${k}: ${k+a}.`};}},
diffDen:{easy(rng){const a=rng.int(2,7),b=rng.int(2,7),n=a+b,d=a*b,g=gcd(n,d)||1;return{prompt:`Вычислите: ${frac(1,a)} + ${frac(1,b)}.`,answer:(d/g===1)?String(n/g):`${n/g}/${d/g}`,solution:`${frac(n,d)}${g>1?' = '+frac(n/g,d/g):''}.`};},medium(rng){const a=rng.int(2,5),b=rng.int(2,5);return{prompt:`Упростите: ${frac(1,`x−${a}`)} + ${frac(1,`x+${b}`)}.`,answer:`(2x+${b-a})/((x-${a})(x+${b}))`,solution:`Общий знаменатель (x−${a})(x+${b}). Числитель: 2x+${b-a}.`};},hard(rng){const a=rng.int(2,4),k=a+rng.int(1,3),num=2*k,den=k*k-a*a,g=gcd(num,den)||1,na=num/g,da=den/g;return{prompt:`Упростите ${frac(1,`x−${a}`)}+${frac(1,`x+${a}`)} и найдите при x=${k}.`,answer:da===1?String(na):`${na}/${da}`,solution:`${frac('2x',`x²−${a*a}`)}. При x=${k}: ${frac(2*k,k*k-a*a)}${g>1?' = '+frac(na,da):''}.`};}},
mulFractions:{easy(rng){const a=rng.int(1,6),b=rng.int(2,9),c=rng.int(2,6),d=rng.int(2,9),n=a*c,den=b*d,g=gcd(n,den)||1;return{prompt:`Вычислите: ${frac(a,b)} · ${frac(c,d)}.`,answer:(den/g===1)?String(n/g):`${n/g}/${den/g}`,solution:`${frac(n,den)}${g>1?' = '+frac(n/g,den/g):''}.`};},medium(rng){const a=rng.int(2,5),b=rng.int(2,5);return{prompt:`Упростите: ${frac(`x²−${a*a}`,`x+${b}`)} · ${frac(`x+${b}`,`x−${a}`)}.`,answer:`x+${a}`,solution:`Сокращаем: x + ${a}.`};},hard(rng){const a=rng.int(2,4),b=rng.int(2,4),k=rng.int(3,8);return{prompt:`Упростите ${frac(`(x+${a})²`,`x+${b}`)} · ${frac(`x+${b}`,`x+${a}`)} и найдите при x=${k}.`,answer:String(k+a),solution:`= x + ${a}. При x=${k}: ${k+a}.`};}},
divFractions:{easy(rng){const a=rng.int(1,6),b=rng.int(2,9),c=rng.int(2,6),d=rng.int(2,9),n=a*d,den=b*c,g=gcd(n,den)||1;return{prompt:`Вычислите: ${frac(a,b)} : ${frac(c,d)}.`,answer:(den/g===1)?String(n/g):`${n/g}/${den/g}`,solution:`${frac(a,b)} · ${frac(d,c)} = ${frac(n,den)}${g>1?' = '+frac(n/g,den/g):''}.`};},medium(rng){const a=rng.int(2,6);return{prompt:`Упростите: ${frac(`x²−${a*a}`,'x−1')} : ${frac(`x−${a}`,'x−1')}.`,answer:`x+${a}`,solution:`${frac(`(x−${a})(x+${a})`,`x−${a}`)} = x + ${a}.`};},hard(rng){const a=rng.int(2,4),b=rng.int(3,6),k=rng.int(3,8);return{prompt:`Упростите ${frac(`x²−${a*a}`,`x+${b}`)} : ${frac(`x−${a}`,`x+${b}`)} и найдите при x=${k}.`,answer:String(k+a),solution:`= x + ${a}. При x=${k}: ${k+a}.`};}},
rootBasic:{easy(rng){const s=[4,9,16,25,36,49,64,81,100,121,144,169,196,225,256,289,324,361,400,441];const n=rng.pick(s),k=Math.sqrt(n);return{prompt:`Вычислите: √${n}.`,answer:String(k),solution:`√${n} = ${k}, т.к. ${k}² = ${n}.`};},medium(rng){const a=rng.pick([4,9,16,25,36,49,64]),b=rng.pick([4,9,16,25,36,49,64,81,100,121]);return{prompt:`Вычислите: √${a} + √${b}.`,answer:String(Math.sqrt(a)+Math.sqrt(b)),solution:`${Math.sqrt(a)} + ${Math.sqrt(b)} = ${Math.sqrt(a)+Math.sqrt(b)}.`};},hard(rng){const a=rng.pick([4,9,16,25,36,49,64]),b=rng.pick([4,9,16,25,36,49]),c=rng.pick([4,9,16,25,36]);return{prompt:`Вычислите: (√${a})² + (√${b})² − √${c}.`,answer:String(a+b-Math.sqrt(c)),solution:`${a}+${b}−${Math.sqrt(c)} = ${a+b-Math.sqrt(c)}.`};}},
rootProps:{easy(rng){const k=rng.int(2,6),m=rng.int(2,5),a=k,b=k*m*m;return{prompt:`Вычислите: √${a} · √${b}.`,answer:String(k*m),solution:`√(${a}·${b}) = √${a*b} = ${k*m}.`};},medium(rng){const p=rng.int(2,4),q=rng.int(2,4),A=p*p*q,B=q;if(A===B)return GENERATORS.rootProps.medium(rng);return{prompt:`Вычислите: √(${A} · ${B}).`,answer:String(p*q),solution:`√${A*B} = ${p*q}.`};},hard(rng){const k=rng.int(2,6),m=rng.int(2,6),A=k*k*m,B=m;return{prompt:`Вычислите: ${frac(`√${A}`,`√${B}`)}.`,answer:String(k),solution:`√${frac(A,B)} = √${k*k} = ${k}.`};}},
rootTransform:{easy(rng){const n=rng.pick([4,9,16,25,36,49,64,81,100,121,144]);return{prompt:`Вычислите: (√${n})².`,answer:String(n),solution:`= ${n}.`};},medium(rng){const a=rng.pick([16,25,36,49,64,81,100]),b=rng.pick([4,9,16,25,36,49]);if(a<=b)return GENERATORS.rootTransform.medium(rng);return{prompt:`Вычислите: √${a} − √${b}.`,answer:String(Math.sqrt(a)-Math.sqrt(b)),solution:`${Math.sqrt(a)} − ${Math.sqrt(b)} = ${Math.sqrt(a)-Math.sqrt(b)}.`};},hard(rng){const m=rng.int(2,4),n=rng.int(2,4),a=m,b=m*n*n,sAB=m*n,val=a+b+2*sAB;return{prompt:`Вычислите: (√${a} + √${b})².`,answer:String(val),solution:`${a}+${b}+2·√${a*b} = ${val}.`};}},
quadEq:{easy(rng){const r1=rng.int(1,6),r2=r1+rng.int(1,5),S=r1+r2,P=r1*r2;return{prompt:`Найдите больший корень уравнения x² − ${S}x + ${P} = 0.`,answer:String(r2),solution:`Корни ${r1} и ${r2}. Больший: ${r2}.`};},medium(rng){const a=rng.pick([2,3]),r1=rng.int(1,4),r2=r1+rng.int(1,3);const b=-a*(r1+r2),c=a*r1*r2,sign=b<0?'−':'+';return{prompt:`Найдите меньший корень уравнения ${a}x² ${sign} ${Math.abs(b)}x + ${c} = 0.`,answer:String(r1),solution:`Корни ${r1} и ${r2}. Меньший: ${r1}.`};},hard(rng){const r=rng.int(3,12),N=r*(r+1);return{prompt:`Произведение двух последовательных натуральных чисел равно ${N}. Найдите меньшее.`,answer:String(r),solution:`n(n+1)=${N} → n=${r}.`};}},
vieta:{easy(rng){const r1=rng.int(1,6),r2=r1+rng.int(1,5),p=-(r1+r2),q=r1*r2;return{prompt:`Найдите сумму корней уравнения x² ${p<0?'−':'+'} ${Math.abs(p)}x + ${q} = 0.`,answer:String(r1+r2),solution:`x₁+x₂ = −p = ${r1+r2}.`};},medium(rng){const r1=rng.int(1,6),r2=r1+rng.int(1,5),p=-(r1+r2),q=r1*r2;return{prompt:`Один корень уравнения x² ${p<0?'−':'+'} ${Math.abs(p)}x + ${q} = 0 равен ${r1}. Найдите другой.`,answer:String(r2),solution:`x₂ = ${r1+r2} − ${r1} = ${r2}.`};},hard(rng){const r1=rng.int(1,5),r2=r1+rng.int(1,4),p=r1+r2,D=r2-r1,q=r1*r2;return{prompt:`Разность корней уравнения x² − ${p}x + q = 0 равна ${D}. Найдите q.`,answer:String(q),solution:`(x₁−x₂)² = p²−4q = ${D*D}. 4q = ${p*p-D*D}, q = ${q}.`};}},
fracEq:{easy(rng){const k=rng.pick([2,3]),xr=rng.int(3,8),b=rng.int(1,xr-2),a=(k-1)*xr-k*b;if(a<=0)return GENERATORS.fracEq.easy(rng);return{prompt:`Решите уравнение ${frac(`x+${a}`,`x−${b}`)} = ${k}.`,answer:String(xr),solution:`x+${a}=${k}(x−${b}). ${a+k*b}=${k-1}x. x=${xr}.`};},medium(rng){const v=rng.pick([{a:2,b:-1,c:1,d:-2,k:2,roots:[1.5,3],bigger:3},{a:3,b:1,c:2,d:-2,k:2,roots:[0,3.5],bigger:3.5}]);return{prompt:`Найдите больший корень уравнения ${frac(v.a,`x ${v.b>=0?'+':'−'} ${Math.abs(v.b)}`)} + ${frac(v.c,`x ${v.d>=0?'+':'−'} ${Math.abs(v.d)}`)} = ${v.k}.`,answer:String(v.bigger),solution:`Корни: ${v.roots.map(ans).join(' и ')}. Больший: ${ans(v.bigger)}.`};},hard(rng){const[p,k,q]=rng.pick([[12,5,13],[3,4,5]]),r1=(p+q)/k,r2=(p-q)/k,big=Math.max(r1,r2);return{prompt:`Найдите больший корень уравнения ${frac(1,'x−1')} + ${frac(1,'x+1')} = ${frac(k,p)}.`,answer:ans(big),solution:`${k}x²−${2*p}x−${k}=0, D=${4*(p*p+k*k)}, √D=${2*q}.<br>Корни ${ans(r1)} и ${ans(r2)}. Больший ${ans(big)}.`};}},
rootEq:{easy(rng){const k=rng.int(2,9);if(rng.next()<0.5){return{prompt:`Решите уравнение √x = ${k}.`,answer:String(k*k),solution:`Возводим обе части в квадрат: x = ${k}² = ${k*k}.<br>Проверка: √${k*k} = ${k} ✓.`};}const a=rng.int(1,10);return{prompt:`Решите уравнение √(x − ${a}) = ${k}.`,answer:String(k*k+a),solution:`x − ${a} = ${k}² = ${k*k}.<br>x = ${k*k} + ${a} = ${k*k+a}.<br>Проверка: √(${k*k+a} − ${a}) = √${k*k} = ${k} ✓.`};},medium(rng){const c=rng.int(3,6);const a=rng.pick([2,3]);const x=rng.int(1,10);const b=c*c-a*x;if(b<0)return GENERATORS.rootEq.medium(rng);return{prompt:`Решите уравнение √(${a}x + ${b}) = ${c}.`,answer:String(x),solution:`Возводим обе части в квадрат: ${a}x + ${b} = ${c}² = ${c*c}.<br>${a}x = ${c*c} − ${b} = ${a*x}.<br>x = ${x}.<br>Проверка: √(${a}·${x}+${b}) = √${c*c} = ${c} ✓.`};},hard(rng){const pairs=[[1,1],[5,1],[11,1],[10,2],[18,2],[3,3],[9,3]];const[a,b]=rng.pick(pairs);const p2=4*b+1+4*a;const p=Math.sqrt(p2);const x1=(2*b+1+p)/2;const x2=(2*b+1-p)/2;const valid=[x1,x2].filter(v=>v-b>=0);const answer=valid[0];const checked=x2<b?`x₂ = ${x2} < ${b}, значит x−${b} < 0 — посторонний корень.`:`x₂ = ${x2} ≥ ${b} — тоже подходит.`;return{prompt:`Решите уравнение √(x + ${a}) = x − ${b}.`,answer:String(answer),solution:`Возводим в квадрат: x + ${a} = (x−${b})² = x² − ${2*b}x + ${b*b}.<br>Получаем: x² − ${2*b+1}x + ${b*b-a} = 0.<br>D = ${p2}, √D = ${p}.<br>x₁ = ${x1}, x₂ = ${x2}.<br>${checked}<br>Ответ: ${answer}.`};}},
/* ===== НОВЫЕ ТЕМЫ ===== */
quadTrinomial:{easy(rng){let r1=rng.int(-6,6),r2=rng.int(-6,6);while(r1===0||r2===0||r1===r2){r1=rng.int(-6,6);r2=rng.int(-6,6);}const b=-(r1+r2),c=r1*r2;const big=Math.max(r1,r2);return{prompt:`Найдите больший корень квадратного трёхчлена ${polyStr(1,b,c)}.`,answer:String(big),solution:`Корни уравнения ${polyStr(1,b,c)} = 0 по теореме Виета: сумма = ${-b}, произведение = ${c}.<br>Корни: ${r1} и ${r2}.<br>Больший: ${big}.`};},medium(rng){const a=rng.pick([1,2,3]);let r1=rng.int(-4,4),r2=r1+rng.int(1,4);const b=-a*(r1+r2),c=a*r1*r2;const D=b*b-4*a*c;if(rng.next()<0.5){const x0=rng.int(-3,3);const val=a*x0*x0+b*x0+c;return{prompt:`Найдите значение трёхчлена ${polyStr(a,b,c)} при x = ${x0}.`,answer:String(val),solution:`Подставляем x = ${x0}:<br>${a}·${x0}² ${b>=0?'+':'−'} ${Math.abs(b)}·${x0} ${c>=0?'+':'−'} ${Math.abs(c)} = ${val}.`};}return{prompt:`Сколько корней имеет трёхчлен ${polyStr(a,b,c)}?`,answer:D>0?'2':D===0?'1':'0',solution:`D = ${b}² − 4·${a}·${c} = ${D}.<br>${D>0?'D > 0 — два корня':D===0?'D = 0 — один корень':'D < 0 — корней нет'}.`};},hard(rng){const k=rng.int(2,6)*(rng.next()<0.5?1:-1);const b=2*k,c=k*k;return{prompt:`При каком значении c трёхчлен ${polyStr(1,b,0)} + c является полным квадратом (имеет единственный корень)?`,answer:String(c),solution:`Единственный корень ⇔ D = 0.<br>D = b² − 4c = ${b*b} − 4c = 0.<br>c = ${b*b}/4 = ${c}.<br>Проверка: ${polyStr(1,b,c)} = (x ${b<0?'+':'−'} ${Math.abs(k)})².`};}},
factorTrinomial:{easy(rng){let r1=rng.int(-5,5),r2=rng.int(-5,5);while(r1===0||r2===0||r1===r2||r1===-r2){r1=rng.int(-5,5);r2=rng.int(-5,5);}const b=-(r1+r2),c=r1*r2;const poly=polyStr(1,b,c);const correct=fFr(r1)+fFr(r2);const w1=fFr(-r1)+fFr(r2);const w2=fFr(r1)+fFr(-r2);const w3=fFr(-r1)+fFr(-r2);const opts=shuffle([correct,w1,w2,w3]);const idx=opts.indexOf(correct)+1;return{prompt:`Разложите на множители: ${poly}.`+options(opts),answer:String(idx),solution:`Корни уравнения ${poly} = 0: x₁ = ${r1}, x₂ = ${r2}.<br>Разложение: a(x−x₁)(x−x₂) = ${correct}.<br>Ответ: вариант ${idx}.`};},medium(rng){const a=rng.pick([2,3]);let r1=rng.int(1,4),r2=r1+rng.int(1,3);if(rng.next()<0.5)r1=-r1;const b=-a*(r1+r2),c=a*r1*r2;const poly=polyStr(a,b,c);const correct=`${a}${fFr(r1)}${fFr(r2)}`;const w1=`${a}${fFr(-r1)}${fFr(r2)}`;const w2=`${a}${fFr(r1)}${fFr(-r2)}`;const w3=`${a}${fFr(-r1)}${fFr(-r2)}`;const opts=shuffle([correct,w1,w2,w3]);const idx=opts.indexOf(correct)+1;return{prompt:`Разложите на множители: ${poly}.`+options(opts),answer:String(idx),solution:`Корни: x₁ = ${r1}, x₂ = ${r2}.<br>Разложение: a(x−x₁)(x−x₂) = ${a}(x−${r1})(x−${r2}).<br>Ответ: вариант ${idx}.`};},hard(rng){const factor=rng.pick([[1,4],[1,9],[1,16],[1,25],[4,9],[4,16],[9,25],[4,25]]);const[p,q]=factor;const pRoot=Math.sqrt(p),qRoot=Math.sqrt(q);const poly=p===1?`x² − ${q}`:`${p}x² − ${q}`;const px=pRoot===1?'x':`${pRoot}x`;const correct=`(${px} − ${qRoot})(${px} + ${qRoot})`;const w1=`(${px} − ${qRoot})²`;const w2=`(${px} + ${qRoot})²`;const w3=`(${px} − ${q})(${px} + ${q})`;const opts=shuffle([correct,w1,w2,w3]);const idx=opts.indexOf(correct)+1;return{prompt:`Разложите на множители: ${poly}.`+options(opts),answer:String(idx),solution:`Формула разности квадратов: a² − b² = (a−b)(a+b).<br>${poly} = (${px})² − ${qRoot}² = ${correct}.<br>Ответ: вариант ${idx}.`};}},
linIneq:{easy(rng){const a=rng.int(2,6),b=rng.int(2,20);if(rng.next()<0.5){const t=b/a,m=Math.floor(t)+1;return{prompt:`Найдите наименьшее целое решение ${a}x > ${b}.`,answer:String(m),solution:`x > ${ans(t)}, наименьшее целое ${m}.`};}const t=b/a,m=Math.ceil(t)-1;return{prompt:`Найдите наибольшее целое решение ${a}x < ${b}.`,answer:String(m),solution:`x < ${ans(t)}, наибольшее целое ${m}.`};},medium(rng){const a=rng.pick([-3,-2,2,3,4]),x0=rng.int(-5,5),b=rng.int(-10,10),c=a*x0+b;const bStr=b>=0?`+ ${b}`:`− ${Math.abs(b)}`;if(a>0)return{prompt:`Наибольшее целое решение ${a}x ${bStr} < ${c}.`,answer:String(x0-1),solution:`x < ${x0}, наибольшее ${x0-1}.`};return{prompt:`Наименьшее целое решение ${a}x ${bStr} < ${c}.`,answer:String(x0+1),solution:`Делим на ${a}<0, знак меняется: x > ${x0}. Наименьшее ${x0+1}.`};},hard(rng){const a=rng.int(2,4);let b=rng.int(1,4);if(b===a)b=a+1;const p=rng.int(1,4),q=rng.int(1,4),coef=a-b,prod=a*p+b*q,tgt=rng.int(-3,3),cVal=coef*tgt-prod;const ineq=`${a}(x−${p})−${b}(x+${q}) < ${cVal}`;if(coef>0)return{prompt:`Наибольшее целое решение ${ineq}.`,answer:String(tgt-1),solution:`${coef}x − ${prod} < ${cVal} → x < ${tgt}. Ответ ${tgt-1}.`};return{prompt:`Наименьшее целое решение ${ineq}.`,answer:String(tgt+1),solution:`${coef}x−${prod}<${cVal}, делим на ${coef}<0, x > ${tgt}. Ответ ${tgt+1}.`};}},
sysIneq:{easy(rng){const a=rng.int(-5,2),b=a+rng.int(3,8),count=b-a-1;return{prompt:`Сколько целых решений у системы { x > ${a}, x < ${b} }?`,answer:String(count),solution:`x ∈ (${a};${b}), целых ${count}.`};},medium(rng){const x0=rng.int(-5,1),x1=x0+rng.int(2,6),b=2*x0,t=(b+1)/2;return{prompt:`Наименьшее целое решение системы { 2x−1 > ${b}, x < ${x1} }.`,answer:String(x0+1),solution:`x > ${ans(t)}, x < ${x1}. Ответ ${x0+1}.`};},hard(rng){const x0=rng.int(-3,3),x1=x0+rng.int(2,5),b1=2*x1-1,b2=3*x0+2;return{prompt:`Наибольшее целое решение системы { 2x−1 < ${b1}, 3x+2 > ${b2} }.`,answer:String(x1-1),solution:`x < ${x1}, x > ${x0}. Ответ ${x1-1}.`};}},
fnDomain:{easy(rng){const k=rng.int(2,5),x0=rng.int(-5,5),b=-k*x0,arg=rng.int(-3,5),r=k*arg+b;const bStr=b>=0?`+ ${b}`:`− ${Math.abs(b)}`;return{prompt:`Дана функция f(x) = ${k}x ${bStr}. Найдите f(${arg}).`,answer:String(r),solution:`${k}·${arg} ${b>=0?'+':'−'} ${Math.abs(b)} = ${r}.`};},medium(rng){const k=rng.int(2,5),x0=rng.int(-6,6),b=-k*x0,bStr=b>=0?`+ ${b}`:`− ${Math.abs(b)}`;return{prompt:`Дана y = ${k}x ${bStr}. Найдите нуль функции.`,answer:String(x0),solution:`${k}x ${b>=0?'+':'−'} ${Math.abs(b)} = 0 → x = ${x0}.`};},hard(rng){const r1=rng.int(-4,0),r2=r1+rng.int(2,5),S=r1+r2,P=r1*r2,tgt=P+rng.int(1,3);return{prompt:`Дана f(x) = x² − ${S}x + ${tgt}. Найдите меньший корень уравнения f(x) = ${P}.`,answer:String(r1),solution:`x²−${S}x+${tgt-P}=0, корни ${r1}, ${r2}. Меньший ${r1}.`};}},
linearFn:{easy(rng){const k=rng.pick([2,3,4,5,-2,-3,-4]);return{prompt:`y = ${k}x + 1. Введите 1, если возрастает, 0 — если убывает.`,answer:k>0?'1':'0',solution:`k ${k>0?'>':'<'} 0 → ${k>0?'возрастает':'убывает'}.`};},medium(rng){const k0=rng.int(2,6),b0=rng.int(-5,5);return{prompt:`Найдите k, при котором y=kx−3 параллелен y=${k0}x ${b0>=0?'+':'−'} ${Math.abs(b0)}.`,answer:String(k0),solution:`k = ${k0}.`};},hard(rng){const x0=rng.int(1,4),y0=rng.int(4,15),b=rng.int(-5,3),k=(y0-b)/x0;if(!Number.isInteger(k)||k<=0)return GENERATORS.linearFn.hard(rng);return{prompt:`При каком k график y = kx ${b>=0?'+':'−'} ${Math.abs(b)} проходит через (${x0}; ${y0})?`,answer:String(k),solution:`${y0} = k·${x0} ${b>=0?'+':'−'} ${Math.abs(b)} → k = ${k}.`};}},
fractionSqrt:{easy(rng){const k=rng.pick([6,8,12,10,15]),x0=rng.int(2,5);if(k%x0!==0)return GENERATORS.fractionSqrt.easy(rng);return{prompt:`Дана y = ${frac(k,'x')}. Найдите y при x = ${x0}.`,answer:String(k/x0),solution:`${frac(k,x0)} = ${k/x0}.`};},medium(rng){const k=rng.pick([4,9,16,25,36,49]);return{prompt:`y = √x. При каком x значение равно ${Math.sqrt(k)}?`,answer:String(k),solution:`√x = ${Math.sqrt(k)} → x = ${k}.`};},hard(rng){const k=rng.pick([12,18,24,30,36]),y0=rng.pick([2,3,4]);if(k%y0!==0)return GENERATORS.fractionSqrt.hard(rng);return{prompt:`y = ${frac(k,'x')}. При каком x значение равно ${y0}?`,answer:String(k/y0),solution:`${frac(k,'x')} = ${y0} → x = ${k/y0}.`};}},
negPow:{easy(rng){const a=rng.pick([2,3,4,5]),n=rng.int(1,4);return{prompt:`Вычислите: ${a}^(−${n}).`,answer:`1/${Math.pow(a,n)}`,solution:`= ${frac(1,Math.pow(a,n))}.`};},medium(rng){const a=rng.pick([2,3,4]),n=rng.int(2,3);return{prompt:`Вычислите: (${frac(1,a)})^(−${n}).`,answer:String(Math.pow(a,n)),solution:`= ${a}^${n} = ${Math.pow(a,n)}.`};},hard(rng){const[a,b]=rng.pick([[2,3],[3,4],[2,5]]),n=rng.int(2,3);const num=Math.pow(b,n),den=Math.pow(a,n),g=gcd(num,den);return{prompt:`Вычислите: (${frac(a,b)})^(−${n}).`,answer:(den/g===1)?String(num/g):`${num/g}/${den/g}`,solution:`= (${frac(b,a)})^${n} = ${frac(num,den)}${g>1?' = '+frac(num/g,den/g):''}.`};}},
powProps:{easy(rng){const a=rng.pick([2,3,5]),m=rng.int(2,4),n=rng.int(1,3);return{prompt:`Вычислите: ${a}^${m} · ${a}^${n}.`,answer:String(Math.pow(a,m+n)),solution:`${a}^${m+n} = ${Math.pow(a,m+n)}.`};},medium(rng){const a=rng.pick([2,3]),m=rng.int(2,3),n=rng.int(2,3);return{prompt:`Вычислите: (${a}^${m})^${n}.`,answer:String(Math.pow(a,m*n)),solution:`${a}^${m*n} = ${Math.pow(a,m*n)}.`};},hard(rng){const a=rng.pick([2,3]),m=rng.int(3,5),n=rng.int(1,2),k=rng.int(1,2),exp=m-n-k;return{prompt:`Вычислите: ${frac(`${a}^${m}`,`${a}^${n} · ${a}^${k}`)}.`,answer:String(Math.pow(a,exp)),solution:`${a}^${exp} = ${Math.pow(a,exp)}.`};}},
stdForm:{easy(rng){const s=rng.pick([{n:520000,o:5},{n:34500,o:4},{n:0.00052,o:-4},{n:0.0032,o:-3},{n:0.000078,o:-5},{n:7300000,o:6}]);return{prompt:`Порядок числа ${s.n} в виде a·10ⁿ (найдите n).`,answer:String(s.o),solution:`${s.n} = a·10^${s.o}. n = ${s.o}.`};},medium(rng){const s=rng.pick([{n:42000,m:'4,2'},{n:0.00071,m:'7,1'},{n:850000,m:'8,5'}]);return{prompt:`Запишите ${s.n} в стандартном виде a·10ⁿ (1 ≤ a < 10). В ответ — a.`,answer:s.m,solution:`${s.n} = ${s.m}·10ⁿ. a = ${s.m}.`};},hard(rng){const a=rng.int(2,6),m=rng.int(2,4),b=rng.int(2,5),n=rng.int(2,3),val=a*b*Math.pow(10,m+n);return{prompt:`Вычислите (${a}·10^${m})·(${b}·10^${n}) как целое число.`,answer:String(val),solution:`${a*b}·10^${m+n} = ${val}.`};}},
quadVertex:{easy(rng){const b=rng.int(-6,6)*2,c=rng.int(-9,9),x0=-b/2;return{prompt:`Найдите x-координату вершины параболы y = x² + ${b}x + ${c}.`,answer:String(x0),solution:`x₀ = −b/(2a) = −${b}/2 = ${x0}.`};},medium(rng){const b=rng.int(-6,6)*2,c=rng.int(-9,9),x0=-b/2,y0=x0*x0+b*x0+c;return{prompt:`Найдите y-координату вершины параболы y = x² + ${b}x + ${c}.`,answer:String(y0),solution:`x₀ = ${x0}; y₀ = ${x0}²+${b}·${x0}+${c} = ${y0}.`};},hard(rng){const m=rng.int(-3,3),n=rng.int(-5,5),a=rng.pick([1,2,-1,-2]),d=rng.pick([2,3]),p=m+d,q=n+a*d*d;return{prompt:`Вершина параболы y = a(x−m)² + n находится в точке (${m}; ${n}), и график проходит через точку (${p}; ${q}). Найдите a.`,answer:String(a),solution:`${q} = a·${p-m}² + ${n} = ${d*d}a + ${n}. ${d*d}a = ${q-n}. a = ${a}.`};}},
quadGraph:{easy(rng){const r1=rng.int(1,5),r2=r1+rng.int(1,4),S=r1+r2,P=r1*r2;return{prompt:`Найдите больший нуль функции y = x² − ${S}x + ${P}.`,answer:String(r2),solution:`Корни ${r1} и ${r2}. Больший ${r2}.`};},medium(rng){const a=rng.int(1,3),b=rng.int(-6,6),c=rng.int(-9,9),x0=rng.int(-3,3),y0=a*x0*x0+b*x0+c;return{prompt:`Дана y = ${a}x² ${b<0?'−':'+'} ${Math.abs(b)}x ${c>=0?'+':'−'} ${Math.abs(c)}. Найдите y при x = ${x0}.`,answer:String(y0),solution:`${y0}.`};},hard(rng){const r1=rng.int(1,5),r2=r1+rng.int(2,5),S=r1+r2,P=r1*r2;return{prompt:`Найдите количество целых решений неравенства x² − ${S}x + ${P} < 0.`,answer:String(r2-r1-1),solution:`Корни ${r1} и ${r2}. Решение (${r1};${r2}). Целых: ${r2-r1-1}.`};}},
rootN:{easy(rng){const b=rng.int(2,5),n=rng.pick([3,4]);const a=Math.pow(b,n);return{prompt:`Вычислите: ${n}-й корень из ${a}.`,answer:String(b),solution:`${b}^${n} = ${a}, корень = ${b}.`};},medium(rng){const a=rng.pick([8,27,64,125]),b=rng.pick([8,27,64,125]);return{prompt:`Вычислите: ∛${a} + ∛${b}.`,answer:String(Math.cbrt(a)+Math.cbrt(b)),solution:`${Math.cbrt(a)} + ${Math.cbrt(b)} = ${Math.cbrt(a)+Math.cbrt(b)}.`};},hard(rng){const b=rng.int(2,4),n=rng.pick([3,4]);const val=Math.pow(b,n);return{prompt:`Вычислите: ${n}-й корень из ${val*val}.`,answer:String(b*b),solution:`= ${b*b}.`};}},
quadIneq:{easy(rng){const a=rng.int(2,6);const target=Math.floor(a*a/2)+1;const minPos=Math.floor(Math.sqrt(target))+1;return{prompt:`Наименьшее натуральное решение x² > ${target}.`,answer:String(minPos),solution:`√${target} ≈ ${Math.sqrt(target).toFixed(2)}. Наименьшее натуральное > √ = ${minPos}.`};},medium(rng){const a=rng.int(1,4),b=a+rng.int(2,5);return{prompt:`Количество целых решений неравенства (x−${a})(x−${b}) < 0.`,answer:String(b-a-1),solution:`Решение (${a};${b}). Целых: ${b-a-1}.`};},hard(rng){const r1=rng.int(-4,0),r2=r1+rng.int(3,6);const sum=r1+r2,prod=r1*r2;let sumPos=0;for(let x=r1+1;x<r2;x++)if(x>0)sumPos+=x;return{prompt:`Решите x² − ${sum}x + ${prod} < 0. Найдите сумму положительных целых решений.`,answer:String(sumPos),solution:`Корни ${r1} и ${r2}. Сумма = ${sumPos}.`};}},
intervalM:{easy(rng){const a=rng.int(-4,0),b=rng.int(2,6);return{prompt:`Наименьшее натуральное решение (x−${a})(x−${b}) > 0.`,answer:String(b+1),solution:`Решение (−∞;${a})∪(${b};+∞). Ответ ${b+1}.`};},medium(rng){const a=rng.int(1,3),b=a+rng.int(1,2),c=b+rng.int(2,4);return{prompt:`Наибольшее целое решение (x−${a})(x−${b})(x−${c}) < 0.`,answer:String(c-1),solution:`Решение (−∞;${a})∪(${b};${c}). Ответ ${c-1}.`};},hard(rng){const a=rng.int(0,2),b=a+rng.int(2,3),c=b+rng.int(2,3);return{prompt:`Наименьшее положительное целое решение (x−${a})(x−${b})(x−${c}) > 0.`,answer:String(a+1),solution:`Решение (${a};${b})∪(${c};+∞). Ответ ${a+1}.`};}},
wholeEq:{easy(rng){const a=rng.int(1,3),b=a+rng.int(1,3),aa=a*a,bb=b*b;return{prompt:`Наибольший корень уравнения x⁴ − ${aa+bb}x² + ${aa*bb} = 0.`,answer:String(b),solution:`t = x², t=${aa} или t=${bb}. x=±${a}, ±${b}. Наибольший ${b}.`};},medium(rng){const a=rng.int(1,3),b=a+rng.int(1,3),aa=a*a,bb=b*b;return{prompt:`Сумма положительных корней x⁴ − ${aa+bb}x² + ${aa*bb} = 0.`,answer:String(a+b),solution:`x=±${a}, ±${b}. Сумма = ${a+b}.`};},hard(rng){const r1=rng.int(-4,-1),r2=rng.int(1,3),r3=r2+rng.int(1,3);const S=r1+r2+r3;return{prompt:`Сумма всех корней x³ − ${S}x² + Px − Q = 0. Найдите S.`,answer:String(S),solution:`По обобщённой теореме Виета S = ${S}.`};}},
graphSys:{easy(rng){const c=rng.int(-3,3),N=rng.pick([-5,-2,0,2,5,8]);const diff=N-c;let count=diff>0?2:diff===0?1:0;return{prompt:`Сколько общих точек у y = x² + ${c} и y = ${N}?`,answer:String(count),solution:`x² = ${diff}. ${diff>0?'Два':diff===0?'Один':'Нет'}.`};},medium(rng){const k=rng.int(-4,4),c=rng.pick([-4,-3,-2,-1,1,2,3,4]);return{prompt:`Сумма абсцисс точек пересечения y = x² и y = ${k>=0?'':'−'}${Math.abs(k)}x ${c>=0?'+':'−'} ${Math.abs(c)}.`,answer:String(k),solution:`По Виета x₁+x₂ = ${k}.`};},hard(rng){const k=rng.int(2,6),b=rng.int(-4,4);if(b===0)return GENERATORS.graphSys.hard(rng);return{prompt:`Произведение абсцисс точек пересечения y = x² и y = ${k}x ${b>=0?'+':'−'} ${Math.abs(b)}.`,answer:String(-b),solution:`x² − ${k}x ${b>=0?'−':'+'} ${Math.abs(b)} = 0. x₁·x₂ = ${-b}.`};}},
sysQuad:{easy(rng){const a=rng.int(1,4),b=a+rng.int(1,3),S=a+b,P=a*b;return{prompt:`Решите { x + y = ${S}, xy = ${P} }. Большее значение x.`,answer:String(b),solution:`Корни t²−${S}t+${P}=0: ${a}, ${b}. Большее x = ${b}.`};},medium(rng){const a=rng.int(1,4),b=a+rng.int(1,3);const S=a+b,D=b-a,sumSq=a*a+b*b;return{prompt:`Решите { x − y = ${D}, x² + y² = ${sumSq} }. Большее значение x.`,answer:String(b),solution:`y = x − ${D}. x = ${a} или x = ${b}. Ответ ${b}.`};},hard(rng){const a=rng.int(1,4),b=a+rng.int(1,3);const sumSq=a*a+b*b,prod=a*b;return{prompt:`Решите { x² + y² = ${sumSq}, xy = ${prod} }. Большее значение |x|.`,answer:String(b),solution:`(x+y)² = ${sumSq+2*prod}. x+y = ±${a+b}. Большее |x| = ${b}.`};}},
ineqVars:{easy(rng){const N=rng.int(2,5);const count=(N+1)*(N+2)/2;return{prompt:`Сколько целых точек (x;y), x ≥ 0, y ≥ 0, x + y ≤ ${N}?`,answer:String(count),solution:`Треугольник. Целых точек: ${count}.`};},medium(rng){const N=rng.int(4,8);let count=0;for(let x=1;x<=N;x++)for(let y=1;y<=N;y++)if(x*y<=N)count++;return{prompt:`Сколько целых точек (x;y), x ≥ 1, y ≥ 1, xy ≤ ${N}?`,answer:String(count),solution:`Всего ${count}.`};},hard(rng){const R2=rng.pick([4,5,8,9,10,13]);let count=0;for(let x=-5;x<=5;x++)for(let y=-5;y<=5;y++)if(x*x+y*y<R2)count++;return{prompt:`Сколько целых точек удовлетворяют x² + y² < ${R2}?`,answer:String(count),solution:`Круг R = √${R2} ≈ ${Math.sqrt(R2).toFixed(2)}. Целых: ${count}.`};}},
arithProg:{easy(rng){const a1=rng.int(2,10),d=rng.int(2,5),n=rng.int(5,12),an=a1+(n-1)*d;return{prompt:`Арифметическая прогрессия: a₁ = ${a1}, d = ${d}. Найдите a<sub>${n}</sub>.`,answer:String(an),solution:`a<sub>n</sub> = a₁ + d(n−1) = ${a1} + ${d}·${n-1} = ${an}.`};},medium(rng){const a1=rng.int(2,8),d=rng.int(2,4),n=rng.int(5,10),an=a1+(n-1)*d,S=n*(a1+an)/2;return{prompt:`Арифметическая прогрессия: a₁ = ${a1}, d = ${d}. Найдите сумму первых ${n} членов.`,answer:String(S),solution:`a<sub>${n}</sub> = ${an}. S = ${frac(`(${a1} + ${an})·${n}`,2)} = ${S}.`};},hard(rng){const a1=rng.int(2,6),d=rng.int(2,4),n1=rng.int(3,6),n2=n1+rng.int(2,5),aN1=a1+(n1-1)*d,aN2=a1+(n2-1)*d;return{prompt:`В арифметической прогрессии a<sub>${n1}</sub> = ${aN1}, a<sub>${n2}</sub> = ${aN2}. Найдите d.`,answer:String(d),solution:`a<sub>${n2}</sub> − a<sub>${n1}</sub> = d·(${n2}-${n1}) = ${aN2-aN1}. d = ${d}.`};}},
geomProg:{easy(rng){const b1=rng.pick([1,2,3]),q=rng.pick([2,3]),n=rng.int(4,6),bn=b1*Math.pow(q,n-1);return{prompt:`Геометрическая прогрессия: b₁ = ${b1}, q = ${q}. Найдите b<sub>${n}</sub>.`,answer:String(bn),solution:`b<sub>n</sub> = b₁·qⁿ⁻¹ = ${b1}·${q}^${n-1} = ${bn}.`};},medium(rng){const b1=rng.pick([2,3]),q=rng.pick([2,3]),n=rng.int(3,5),S=b1*(Math.pow(q,n)-1)/(q-1);return{prompt:`Геометрическая прогрессия: b₁ = ${b1}, q = ${q}. Найдите сумму первых ${n} членов.`,answer:String(S),solution:`S = ${frac(`b₁(qⁿ − 1)`,'q − 1')} = ${frac(`${b1}·(${q}^${n} − 1)`,`${q} − 1`)} = ${S}.`};},hard(rng){const q=rng.pick([2,3]),b1=rng.pick([1,2,3]),n1=rng.int(2,3),n2=n1+rng.int(1,2),bN1=b1*Math.pow(q,n1-1),bN2=b1*Math.pow(q,n2-1);return{prompt:`В геометрической прогрессии b<sub>${n1}</sub> = ${bN1}, b<sub>${n2}</sub> = ${bN2}. Найдите q (q > 0).`,answer:String(q),solution:`q^${n2-n1} = ${bN2}/${bN1} = ${Math.pow(q,n2-n1)}. q = ${q}.`};}},
progMix:{easy(rng){const a1=rng.int(1,5),d=rng.int(1,3);return{prompt:`Определите вид прогрессии: ${a1}; ${a1+d}; ${a1+2*d}; ${a1+3*d}; ... Введите 1, если арифметическая, 2 — если геометрическая.`,answer:'1',solution:`Разность между членами постоянна: ${d}. Арифметическая.`};},medium(rng){const b1=rng.pick([1,2]),q=rng.pick([2,3]);return{prompt:`Геометрическая прогрессия: b₁ = ${b1}, q = ${q}. Найдите b₁ + b₂ + b₃.`,answer:String(b1+b1*q+b1*q*q),solution:`b₂ = ${b1*q}, b₃ = ${b1*q*q}. Сумма = ${b1+b1*q+b1*q*q}.`};},hard(rng){const a1=rng.int(2,5),d=rng.int(2,4),n=rng.int(5,8),an=a1+(n-1)*d,S=n*(a1+an)/2;return{prompt:`Сумма первых ${n} членов арифметической прогрессии равна ${S}. a₁ = ${a1}. Найдите d.`,answer:String(d),solution:`a<sub>${n}</sub> = ${an}. ${an} = ${a1} + ${d}·${n-1}. d = ${d}.`};}},
combTasks:{easy(rng){const n=rng.int(3,6),fact=factorial(n);return{prompt:`Вычислите ${n}! (факториал).`,answer:String(fact),solution:`${n}! = 1·2·3·...·${n} = ${fact}.`};},medium(rng){const n=rng.int(4,7),k=rng.int(2,n-1),C=factorial(n)/(factorial(k)*factorial(n-k));return{prompt:`Вычислите число сочетаний C(${n}; ${k}).`,answer:String(C),solution:`C(${n};${k}) = ${n}!/(${k}!·${n-k}!) = ${C}.`};},hard(rng){const items=rng.int(5,8),choice=rng.int(2,4),A=factorial(items)/factorial(items-choice);return{prompt:`Сколькими способами можно выбрать ${choice} человек из ${items} на разные должности?`,answer:String(A),solution:`A(${items};${choice}) = ${items}!/(${items}−${choice})! = ${A}.`};}},
probability:{easy(rng){const total=rng.int(10,20),red=rng.int(2,total-2);return{prompt:`В коробке ${total} карандашей, из них ${red} красных. Наугад достают один. Какова вероятность, что он красный?`,answer:ans(red/total),solution:`P = ${frac(red,total)} = ${ans(red/total)}.`};},medium(rng){const sum=rng.int(4,10),ways=6-Math.abs(sum-7);return{prompt:`Игральную кость бросают дважды. Найдите вероятность того, что сумма очков равна ${sum}.`,answer:ans(ways/36),solution:`Всего 36, благоприятных ${ways}. P = ${frac(ways,36)} ≈ ${ans(ways/36)}.`};},hard(rng){const total=rng.int(20,50),red=rng.int(5,15),green=rng.int(5,15),blue=total-red-green;if(blue<3)return GENERATORS.probability.hard(rng);return{prompt:`В урне ${total} шаров: ${red} красных, ${green} зелёных, ${blue} синих. Наугад достают один. Найдите вероятность, что он НЕ красный.`,answer:ans((green+blue)/total),solution:`P(не красный) = ${frac(green+blue,total)} = ${ans((green+blue)/total)}.`};}},
freq:{easy(rng){const n=rng.pick([100,200,300,500]),m=rng.int(10,n-10);return{prompt:`Из ${n} деталей ${m} бракованных. Найдите относительную частоту брака.`,answer:ans(m/n),solution:`Частота = ${frac(m,n)} = ${ans(m/n)}.`};},medium(rng){const n=rng.pick([500,800,1000,2000]),m=rng.int(50,Math.floor(n/2));return{prompt:`Монету бросили ${n} раз, орёл выпал ${m} раз. Найдите относительную частоту выпадения орла.`,answer:ans(m/n),solution:`Частота = ${frac(m,n)} = ${ans(m/n)}.`};},hard(rng){const n=rng.pick([1000,1500,2000]),p=rng.pick([0.3,0.4,0.5]),m=Math.round(n*p);return{prompt:`В серии из ${n} выстрелов стрелок поразил мишень ${m} раз. Оцените вероятность попадания по относительной частоте.`,answer:ans(m/n),solution:`P ≈ ${frac(m,n)} = ${ans(m/n)}.`};}}
};

function buildTraining(theme,seed){if(!GENERATORS[theme.generator])return Array(10).fill(0).map((_,i)=>({prompt:`<p>Тема «${theme.name}» в разработке.</p>`,answer:'',solution:'—',stub:true,difficulty:'easy',n:i+1,topic:theme.name}));const rng=makeRng(seed),gen=GENERATORS[theme.generator],tasks=[];for(let i=0;i<4;i++)tasks.push({...gen.easy(rng),difficulty:'easy'});for(let i=0;i<4;i++)tasks.push({...gen.medium(rng),difficulty:'medium'});for(let i=0;i<2;i++)tasks.push({...gen.hard(rng),difficulty:'hard'});return tasks.map((t,i)=>({...t,n:i+1,topic:theme.name}));}
function buildTest(chapter,seed){const active=chapter.themes.filter(t=>GENERATORS[t.generator]);if(!active.length)return Array(10).fill(0).map((_,i)=>({prompt:'Задания появятся позже.',answer:'',solution:'—',stub:true,difficulty:'easy',n:i+1,topic:chapter.title}));const rng=makeRng(seed),plan=['easy','easy','easy','easy','medium','medium','medium','medium','hard','hard'];return plan.map((diff,i)=>{const theme=active[i%active.length];return{...GENERATORS[theme.generator][diff](rng),difficulty:diff,n:i+1,topic:theme.name};});}

const settings=JSON.parse(localStorage.getItem('alg-settings')||'{"light":false,"touch":false,"openChapters":{}}');settings.openChapters=settings.openChapters||{};
const saveSettings=()=>localStorage.setItem('alg-settings',JSON.stringify(settings));
const state={grade:8,chapterId:null,themeId:null,mode:null,tasks:[],answers:{},revealed:{},finished:false,startTime:0,seed:0};
let timerHandle=0,logoTaps=[];

const ICONS={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.4 1.4M17.6 17.6L19 19M5 19l1.4-1.4M17.6 6.4L19 5"/>',moon:'<path d="M20 14.5A8 8 0 1 1 9.5 4 6.5 6.5 0 0 0 20 14.5z"/>',touch:'<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/>',home:'<path d="M3 11l9-7 9 7"/><path d="M5 10v10h14V10"/>',calc:'<rect x="5" y="2" width="14" height="20" rx="3"/><path d="M8 6h8M8 11h.01M12 11h.01M16 11h.01M8 15h.01M12 15h.01M16 15h.01M8 18.5h8"/>',ref:'<path d="M12 6c-2-1.5-5-2-8-1.5v14c3-.5 6 0 8 1.5 2-1.5 5-2 8-1.5v-14c-3-.5-6 0-8 1.5z"/><path d="M12 6v14"/>',pen:'<path d="M4 20l4-1 11-11-3-3L5 16z"/><path d="M14 7l3 3"/>',close:'<path d="M6 6l12 12M18 6L6 18"/>',line:'<path d="M5 19L19 5"/><circle cx="5" cy="19" r="1.6"/><circle cx="19" cy="5" r="1.6"/>',paper:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M4 14l5-4 4 3 3-2 4 3"/>',undo:'<path d="M9 14L4 9l5-5"/><path d="M4 9h10a6 6 0 0 1 0 12h-3"/>',broom:'<path d="M19 3l-7 8"/><path d="M12 11l-3 1-5 8h10l2-6z"/><path d="M8 20l2-4M11 20l1-4"/>'};
function svgIcon(n){return`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${ICONS[n]}</svg>`;}

function init(){$('#logo').innerHTML=`<div class="logo-icon"><svg viewBox="0 0 32 32"><path d="M6 9h20M16 4v12M8 22l8 6 8-6M8 22h16" stroke="#fff" stroke-width="2.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg></div><div><b>Алгебра · тренажёр</b><small>8–9 класс</small></div>`;$('#themeBtn').innerHTML=svgIcon(settings.light?'moon':'sun');$('#touchBtn').innerHTML=svgIcon('touch');$('#homeBtn').innerHTML=svgIcon('home');$('#calcBtn').innerHTML=svgIcon('calc');$('#refBtn').innerHTML=svgIcon('ref');$('#boardBtn').innerHTML=svgIcon('pen');$('#closeBtn').innerHTML=svgIcon('close');applyLook();initMax();showHome();}
function applyLook(){document.body.classList.toggle('light',settings.light);document.body.classList.toggle('touch',settings.touch);$('#themeBtn').innerHTML=svgIcon(settings.light?'moon':'sun');$('#touchBtn').classList.toggle('on',settings.touch);}
function initMax(){const wa=window.WebApp;if(!wa)return;if(wa.ready)wa.ready();if(wa.expand)wa.expand();}
function toast(t){const b=$('#toast');b.textContent=t;b.classList.add('show');clearTimeout(b.hideTimer);b.hideTimer=setTimeout(()=>b.classList.remove('show'),1800);}
function render(html,preserve){const y=preserve?window.scrollY:0;$('#view').innerHTML=`<div class="view">${html}</div>`;if(preserve)window.scrollTo({top:y,behavior:'auto'});else window.scrollTo({top:0,behavior:'smooth'});}

function chapterBodyHtml(c){const themes=c.themes.map(t=>`<div class="theme-row"><span class="theme-name">${t.name}</span>${!GENERATORS[t.generator]?'<span class="tag stub">скоро</span>':''}<button class="btn small ${!GENERATORS[t.generator]?'ghost':''}" ${!GENERATORS[t.generator]?'disabled':''} onclick="event.stopPropagation();startTrain('${c.id}','${t.id}')">Тренировка</button><button class="btn small ghost" onclick="event.stopPropagation();showTheory('${t.id}')">Теория</button></div>`).join('');const theoryBtn=c.themes.some(t=>THEORY[t.id])?`<button class="btn ghost" onclick="event.stopPropagation();showChapterTheory('${c.id}')">Теория по главе</button>`:'';return`<div class="chapter-body">${themes}<div class="row" style="margin-top:10px">${theoryBtn}<button class="btn gold" onclick="event.stopPropagation();startTest('${c.id}')">Контрольная по главе</button></div></div>`;}
function showHome(){stopTimer();const list=CHAPTERS.filter(c=>c.grade===state.grade).map(c=>{const isOpen=!!settings.openChapters[c.id];return`<div class="chapter ${isOpen?'open':'closed'}" data-chapter="${c.id}"><div class="chapter-head" onclick="toggleChapter('${c.id}')"><span class="chevron">▸</span><h3>${c.title}</h3><small>${c.themes.length} тем</small></div>${isOpen?chapterBodyHtml(c):''}</div>`;}).join('');const anyOpen=Object.keys(settings.openChapters).some(id=>settings.openChapters[id]);render(`<div class="hero"><h1>Готовимся к алгебре</h1><p>8 класс — 6 глав, 9 класс — 5 глав. Полный цикл: тренировка → теория → контрольная → оценка.</p></div><div class="tabs"><div class="tab ${state.grade===8?'on':''}" onclick="state.grade=8;showHome()">8 класс</div><div class="tab ${state.grade===9?'on':''}" onclick="state.grade=9;showHome()">9 класс</div><button class="btn small ghost" onclick="toggleAllChapters(${!anyOpen})">${anyOpen?'Свернуть все':'Открыть все'}</button></div>${list}`);}
function toggleChapter(id){settings.openChapters[id]=!settings.openChapters[id];saveSettings();const c=CHAPTERS.find(c=>c.id===id),el=document.querySelector(`[data-chapter="${id}"]`);if(!c||!el)return;const isOpen=!!settings.openChapters[id];el.classList.toggle('open',isOpen);el.classList.toggle('closed',!isOpen);const body=el.querySelector('.chapter-body');if(isOpen&&!body)el.insertAdjacentHTML('beforeend',chapterBodyHtml(c));else if(!isOpen&&body)body.remove();}
function toggleAllChapters(open){CHAPTERS.forEach(c=>{if(c.grade===state.grade)settings.openChapters[c.id]=open;});saveSettings();showHome();}
function showTheory(id){const c=CHAPTERS.find(c=>c.themes.some(t=>t.id===id));if(!c)return;const t=c.themes.find(t=>t.id===id);const body=THEORY[t.id]||`<p>Теория появится вместе с генератором.</p>`;openSheet(`Теория: ${t.name}`,`<div class="ref">${body}</div>`);}
function showChapterTheory(id){const c=CHAPTERS.find(c=>c.id===id);if(!c)return;const body=c.themes.map(t=>{const th=THEORY[t.id];return th?`<h3>${t.name}</h3>${th}`:'';}).join('');if(!body)return toast('Теории нет');openSheet(`Теория по главе: ${c.title}`,`<div class="ref">${body}</div>`);}

function startTrain(cid,tid){const c=CHAPTERS.find(c=>c.id===cid),t=c.themes.find(t=>t.id===tid);state.chapterId=cid;state.themeId=tid;state.mode='train';state.seed=Date.now()%2147483647;state.tasks=buildTraining(t,state.seed);state.answers={};state.revealed={};state.finished=false;renderTrain();}
function renderTrain(){const c=CHAPTERS.find(c=>c.id===state.chapterId),t=c.themes.find(t=>t.id===state.themeId);const cards=state.tasks.map(t=>renderTask(t,true)).join('');render(`<div class="bar"><h2>${t.name}</h2><button class="btn ghost small" onclick="showHome()">← К темам</button></div><div class="row" style="margin-bottom:12px"><button class="btn green" onclick="newExamples()">Новые примеры</button><button class="btn ghost" onclick="showTheory('${t.id}')">Теория</button></div>${cards}`);}
function newExamples(){const c=CHAPTERS.find(c=>c.id===state.chapterId),t=c.themes.find(t=>t.id===state.themeId);state.seed=Date.now()%2147483647;state.tasks=buildTraining(t,state.seed);state.answers={};state.revealed={};renderTrain();}

function renderTask(t,allow){const ll=t.difficulty==='easy'?'простое':t.difficulty==='medium'?'среднее':'сложное';const a=state.answers[t.n]??'',rev=state.revealed[t.n],hint=answerHint(t);const input=t.stub?'<p style="color:var(--muted)">Заглушка</p>':`<div class="answer-row"><input class="input" id="inp-${t.n}" placeholder="Введите ответ" value="${esc(a)}" ${rev?'disabled':''} oninput="state.answers[${t.n}]=this.value" onkeydown="if(event.key==='Enter')checkTask(${t.n})">${allow&&!rev?`<button class="btn" onclick="checkTask(${t.n})">Проверить</button><button class="btn ghost" onclick="revealTask(${t.n})">Решение</button>`:''}</div>${!rev&&!t.stub?`<div class="input-hint">${hint}</div>`:''}`;let fb='';if(rev){const ok=t.stub?false:check(state.answers[t.n],t);fb=`<div class="verdict ${ok?'ok':'bad'}">${ok?'Верно!':`Неверно. Правильный ответ: ${fmtAnswer(t.answer)}`}</div><div class="solution"><b class="h">Ответ:</b> ${fmtAnswer(t.answer)}<br><b class="h">Решение:</b><br>${t.solution}</div>`;}return`<div class="task" id="task-${t.n}"><div class="task-head"><span class="num">№ ${t.n}</span><span class="level ${t.difficulty}">${ll}</span></div><div class="task-text">${t.prompt}</div>${input}${fb}</div>`;}
function answerHint(t){if(t.stub)return'';const a=t.answer||'';if(/^-?\d+\/\d+$/.test(a))return'Ответ: дробь или десятичная';if(/[xyzabmn]/i.test(a))return'Ответ: выражение, например x+2';return'Ответ: число';}
function esc(s){return String(s).replace(/"/g,'&quot;');}
function checkTask(n){const t=state.tasks.find(x=>x.n===n);if(!t||t.stub)return;const inp=$(`#inp-${n}`);if(inp)state.answers[n]=inp.value;state.revealed[n]=true;rerender(n);}
function revealTask(n){state.revealed[n]=true;rerender(n);}
function rerender(n){const cards=state.tasks.map(x=>renderTask(x,true)).join('');const c=CHAPTERS.find(c=>c.id===state.chapterId),t=c.themes.find(t=>t.id===state.themeId);const bar=`<div class="bar"><h2>${t.name}</h2><button class="btn ghost small" onclick="showHome()">← К темам</button></div><div class="row" style="margin-bottom:12px"><button class="btn green" onclick="newExamples()">Новые примеры</button><button class="btn ghost" onclick="showTheory('${t.id}')">Теория</button></div>`;render(bar+cards,true);if(n!==undefined){const v=document.querySelector(`#task-${n} .verdict`);if(v)v.scrollIntoView({behavior:'smooth',block:'nearest'});}}

const TEST_MINUTES=40;
function startTest(cid){const c=CHAPTERS.find(c=>c.id===cid);state.chapterId=cid;state.mode='test';state.tasks=buildTest(c,Date.now()%2147483647);state.answers={};state.revealed={};state.finished=false;state.startTime=Date.now();startTimer();renderTest();}
function renderTest(){const c=CHAPTERS.find(c=>c.id===state.chapterId);const cards=state.tasks.map(t=>renderTask(t,false)).join('');render(`<div class="bar"><h2>Контрольная: ${c.title}</h2><span class="timer" id="timer">40:00</span></div><p style="color:var(--muted);margin:0 0 12px">10 заданий · 40 минут · Проверка после сдачи</p>${cards}<div class="row" style="margin-top:14px"><button class="btn gold" onclick="confirmFinish()">Сдать</button><button class="btn ghost" onclick="cancelTest()">Отменить</button></div>`);updateTimer();}
function startTimer(){stopTimer();timerHandle=setInterval(updateTimer,1000);}
function stopTimer(){if(timerHandle)clearInterval(timerHandle);timerHandle=0;}
function updateTimer(){const b=$('#timer');if(!b)return;const el=Math.floor((Date.now()-state.startTime)/1000),left=Math.max(0,TEST_MINUTES*60-el);const mm=String(Math.floor(left/60)).padStart(2,'0'),ss=String(left%60).padStart(2,'0');b.textContent=`${mm}:${ss}`;b.classList.toggle('warn',left<300);if(left===0)finishTest();}
function confirmFinish(){const empty=state.tasks.filter(t=>!state.answers[t.n]).length;if(confirm(empty?`Без ответа: ${empty}. Сдать?`:'Сдать?'))finishTest();}
function finishTest(){stopTimer();state.finished=true;state.tasks.forEach(t=>state.revealed[t.n]=true);renderResult();}
function cancelTest(){if(!confirm('Точно отменить?'))return;stopTimer();showHome();}
function renderResult(){let correct=0;state.tasks.forEach(t=>{if(t.stub)return;if(check(state.answers[t.n],t))correct++;});const grade=correct>=9?5:correct>=7?4:correct>=5?3:2;const cards=state.tasks.map(t=>renderTask(t,false)).join('');render(`<div class="task result"><div class="grade g${grade}">${grade}</div><h2>Оценка: ${grade}</h2><div class="score-line"><span>Правильно: ${correct} из ${state.tasks.length}</span></div><div class="row"><button class="btn ghost" onclick="showHome()">К главам</button><button class="btn gold" onclick="startTest('${state.chapterId}')">Новый вариант</button></div></div>${cards}`);}

function onLogoTap(){const now=Date.now();logoTaps=logoTaps.filter(t=>now-t<2500);logoTaps.push(now);if(logoTaps.length<5){showHome();return;}logoTaps=[];const chs=CHAPTERS;const body=`<p>PDF с двумя вариантами контрольной и листом ответов.</p>${chs.map(c=>`<div class="row" style="margin-bottom:8px"><b style="flex:1">${c.title}</b><button class="btn small" onclick="printTest('${c.id}')">Печать</button></div>`).join('')}`;openSheet('Секретная печать',body);}
function printTest(cid){closeSheet();const c=CHAPTERS.find(c=>c.id===cid);const sA=Date.now()%2147483647,sB=sA+7919;const tA=buildTest(c,sA),tB=buildTest(c,sB);const code=String(Math.floor(Math.random()*9000)+1000);const rv=(t,l)=>`<h1>${c.title} · Вариант ${l}</h1><div class="meta">Код ${code}-${l} · 40 минут · 10 заданий</div>${t.map(x=>`<div class="ptask"><b>${x.n}.</b> ${x.prompt}<br><span class="ans-line"></span></div>`).join('')}<div class="page"></div>`;const ans2=(t,l)=>`<h2>Ответы · Вариант ${l} (код ${code}-${l})</h2><table><tr><th>№</th><th>Ответ</th><th>Решение</th></tr>${t.map(x=>`<tr><td>${x.n}</td><td>${fmtAnswer(x.answer)||'—'}</td><td>${x.solution}</td></tr>`).join('')}</table>`;$('#print').innerHTML=rv(tA,'А')+rv(tB,'Б')+`<div class="page">${ans2(tA,'А')}</div><div class="page">${ans2(tB,'Б')}</div>`;setTimeout(()=>window.print(),200);}

const CALC_KEYS=['C','(',')','÷','7','8','9','×','4','5','6','−','1','2','3','+','√','0',',','=','x²','^','⌫','π'];
let calcExpr='';
function openCalculator(){const keys=CALC_KEYS.map(k=>`<button class="btn ${/[0-9,]/.test(k)?'ghost':k==='='?'gold':''}" onclick="calcPress('${k}')">${k}</button>`).join('');openSheet('Калькулятор',`<div class="calc-screen"><small id="calcHint"></small><span id="calcView">${calcExpr||'0'}</span></div><div class="calc-keys">${keys}</div>`);}
function calcPress(k){const hint=$('#calcHint');hint.textContent='';if(k==='C')calcExpr='';else if(k==='⌫')calcExpr=calcExpr.slice(0,-1);else if(k==='x²')calcExpr+='^2';else if(k==='√')calcExpr+='√(';else if(k==='='){const r=evaluate(calcExpr);hint.textContent=calcExpr+' =';calcExpr=r===null?'':String(rnd(r));if(r===null)hint.textContent='Ошибка';}else calcExpr+=k;$('#calcView').textContent=calcExpr||'0';}
function evaluate(expr){const code=expr.replace(/,/g,'.').replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').replace(/π/g,'(Math.PI)').replace(/√/g,'Math.sqrt').replace(/\^/g,'**');if(!/^[0-9+\-*/().\sMathsqrtPI]*$/.test(code))return null;try{const v=Function('"use strict";return('+code+')')();return typeof v==='number'&&isFinite(v)?v:null;}catch{return null;}}

function openReference(){openSheet('Справочник','<div class="ref">'+REFERENCE.map(([t,l])=>`<h4>${t}</h4>`+l.map(x=>`<p>${x}</p>`).join('')).join('')+squaresTable()+trigTables()+'</div>');}

const BOARD_COLORS=['#4283d8','#2c5fa8','#3dbe8b','#2f8f7a','#e07a7e','#e58f5a','#e3b04b','#9b7be0','#d77bb0','#5bb8c9','#8a94a6','#1f2433'];
const BOARD_WIDTHS=[2,4,7,11,16];
const board={tool:'pen',color:BOARD_COLORS[0],width:BOARD_WIDTHS[1],paper:true,strokes:[],current:null,ready:false};
function openBoard(){closeSheet();if(!board.ready)setupBoard();$('#board').classList.add('show');resizeBoard();}
function closeBoard(){$('#board').classList.remove('show');}
function setupBoard(){const c=$('#boardCanvas');c.addEventListener('pointerdown',startStroke);c.addEventListener('pointermove',moveStroke);c.addEventListener('pointerup',endStroke);c.addEventListener('pointercancel',endStroke);window.addEventListener('resize',()=>{if($('#board').classList.contains('show'))resizeBoard();});board.ready=true;renderBoardBar();}
function renderBoardBar(){const tb=(n,t,a,on)=>`<button class="tool${on?' on':''}" title="${t}" onclick="${a}">${svgIcon(n)}</button>`;const ws=BOARD_WIDTHS.map(w=>`<button class="tool${w===board.width?' on':''}" onclick="setBW(${w})"><i class="bw" style="width:${w+2}px;height:${w+2}px"></i></button>`).join('');const cs=BOARD_COLORS.map(c=>`<button class="swatch${c===board.color?' on':''}" style="background:${c}" onclick="setBC('${c}')"></button>`).join('');$('#boardBar').innerHTML=`<div class="bgroup">${tb('pen','Кисть',"setBT('pen')",board.tool==='pen')}${tb('line','Прямая',"setBT('line')",board.tool==='line')}</div><div class="bgroup">${ws}</div><div class="bgroup colors">${cs}</div><div class="bgroup">${tb('paper','Фон','toggleBP()',board.paper)}${tb('undo','Отменить','undoStroke()')}${tb('broom','Очистить','clearBoard()')}<button class="tool" onclick="closeBoard()">${svgIcon('close')}</button></div>`;$('#board').classList.toggle('paper',board.paper);}
function setBT(t){board.tool=t;renderBoardBar();}
function setBW(w){board.width=w;renderBoardBar();}
function setBC(c){board.color=c;renderBoardBar();}
function toggleBP(){board.paper=!board.paper;renderBoardBar();}
function undoStroke(){board.strokes.pop();drawBoard();}
function clearBoard(){board.strokes=[];drawBoard();}
function resizeBoard(){const c=$('#boardCanvas'),r=window.devicePixelRatio||1;c.width=Math.round(c.clientWidth*r);c.height=Math.round(c.clientHeight*r);c.getContext('2d').setTransform(r,0,0,r,0,0);drawBoard();}
function boardPoint(e){const r=$('#boardCanvas').getBoundingClientRect();return[e.clientX-r.left,e.clientY-r.top];}
function startStroke(e){e.preventDefault();e.target.setPointerCapture(e.pointerId);const p=boardPoint(e);board.current={tool:board.tool,color:board.color,width:board.width,points:[p,p]};drawBoard();}
function moveStroke(e){if(!board.current)return;const p=boardPoint(e);if(board.current.tool==='line')board.current.points[1]=p;else board.current.points.push(p);drawBoard();}
function endStroke(){if(!board.current)return;board.strokes.push(board.current);board.current=null;}
function drawBoard(){const c=$('#boardCanvas'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.lineCap='round';ctx.lineJoin='round';board.strokes.concat(board.current?[board.current]:[]).forEach(s=>{ctx.strokeStyle=s.color;ctx.lineWidth=s.width;ctx.beginPath();s.points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke();});}

function openSheet(t,b){$('#sheetTitle').textContent=t;$('#sheetBody').innerHTML=b;$('#overlay').classList.add('show');}
function closeSheet(){$('#overlay').classList.remove('show');}
function toggleTheme(){settings.light=!settings.light;saveSettings();applyLook();}
function toggleTouch(){settings.touch=!settings.touch;saveSettings();applyLook();toast(settings.touch?'Режим тач-панели':'Обычный режим');}

document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeSheet();closeBoard();}});
document.addEventListener('DOMContentLoaded',init);
